from copy import deepcopy
from html import escape
import re


class TagError(ValueError):
    pass


_NAME = re.compile(r"^[a-z][a-z0-9-]*$")
_VOID = {"br", "hr", "img", "input", "meta", "link"}
_REQUIRED = {"img": "src", "link": "href"}


class Element:
    def __init__(self, name, *children, safe=False, **attributes):
        if not isinstance(name, str) or not _NAME.fullmatch(name):
            raise ValueError("invalid tag name")
        if not isinstance(safe, bool):
            raise TypeError("safe must be a boolean")
        if name in _VOID and children:
            raise TagError("void tags cannot have children")
        if "class_" in attributes and "class" in attributes:
            raise ValueError("class specified twice")
        if "class_" in attributes:
            attributes["class"] = attributes.pop("class_")
        self.name = name
        self.safe = safe
        self._attributes = deepcopy(attributes)
        self._children = []
        self._validate_attributes()
        self.append(*children)

    def _validate_attributes(self):
        for key, value in self._attributes.items():
            if not isinstance(key, str) or not _NAME.fullmatch(key):
                raise ValueError("invalid attribute name")
            if key == "class" and not isinstance(value, str):
                try:
                    value = list(value)
                except TypeError as exc:
                    raise TypeError("class must be a string or iterable of strings") from exc
                if any(not isinstance(item, str) for item in value):
                    raise TypeError("class entries must be strings")
                self._attributes[key] = value
            elif isinstance(value, bool) or value is None:
                continue
            elif not isinstance(value, (str, int)):
                raise TypeError("invalid attribute value")

    def append(self, *children):
        if self.name in _VOID and children:
            raise TagError("void tags cannot have children")
        for child in children:
            if isinstance(child, bool) or not isinstance(child, (str, int, Element)):
                raise TypeError("invalid child")
        self._children.extend(children)
        return self

    def render(self):
        required = _REQUIRED.get(self.name)
        if required is not None and self._attributes.get(required) in (None, False, ""):
            raise KeyError(required)
        rendered = []
        for key in sorted(self._attributes):
            value = self._attributes[key]
            if value is False or value is None:
                continue
            if key == "class" and not isinstance(value, str):
                value = " ".join(value)
                if not value:
                    continue
            if value is True:
                rendered.append(key)
            else:
                rendered.append(f'{key}="{escape(str(value), quote=True)}"')
        opening = self.name + ((" " + " ".join(rendered)) if rendered else "")
        if self.name in _VOID:
            return f"<{opening}>"
        body = "".join(
            child.render() if isinstance(child, Element)
            else str(child) if not self.safe and isinstance(child, str)
            else escape(str(child), quote=True)
            for child in self._children
        )
        return f"<{opening}>{body}</{self.name}>"

    def __str__(self):
        return self.render()


def make(name, *children, **attributes):
    return Element(name, *children, **attributes)

